cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('../results/FS-Filters-executed.ipynb', as_version=4)
for idx in [2,3,7,8,10,17,19,20,22,23]:
    cell=nb.cells[idx]
    print('CELL', idx, cell.cell_type)
    for out in cell.get('outputs',[]):
        if out.output_type=='stream':
            print('STREAM', out.text[:500])
        elif out.output_type=='execute_result':
            print('RESULT', out['data'].get('text/plain','')[:1000])
        elif out.output_type=='display_data':
            print('DISPLAY keys', out['data'].keys())
    print('---')
PY

